import collections
def comps(g):
    g=list(g); seen=set(); out=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]==7 and (i,j) not in seen:
                c=[(i,j)]; stack=[(i,j)]; seen.add((i,j))
                while stack:
                    y,x=stack.pop()
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        n=(y+di,x+dj)
                        if 0<=n[0]<len(g) and 0<=n[1]<len(g[0]) and g[n[0]][n[1]]==7 and n not in seen:
                            seen.add(n); c.append(n); stack.append(n)
                out.append(c)
    return out
