def f(g,shape=7):
    pts=[(i,j) for i in range(len(g)) for j in range(len(g[0])) if g[i][j]==shape]
    r0,r1=min(p[0] for p in pts),max(p[0] for p in pts)
    c0,c1=min(p[1] for p in pts),max(p[1] for p in pts)
    o=[row[:] for row in g]
    for j in range(c0,c1+1):
        for i in (r0,r1):
            if o[i][j]!=shape: o[i][j]=2
    for i in range(r0,r1+1):
        for j in (c0,c1):
            if o[i][j]!=shape: o[i][j]=2
    return o
